"""Repair log parsing and collect the one already-acknowledged recovery2 startup. Calls require --execute."""
from pathlib import Path
from datetime import datetime, timezone
import hashlib, json, os, subprocess, sys, urllib.request

COMMIT='9dd9c85fb674528a2c1dd1b0138f5a2d87ba683e';DEPLOYMENT='f6d77b2e-6886-429b-a4d2-4873c9199ce8';IMAGE='sha256:3e4c2c91591a5598a85f63b4099b1b4890588ce79ec832b21b7d284b5aa89d1b'
PROJECT='119f3652-9d84-4d16-983c-1a17c0fd1aaa';ENVIRONMENT='6642d65a-15a2-41e9-b25e-b7b01990aa28';SERVICE='f43abcf9-72f0-4034-828a-8d83ca26b0db'
ADMISSION='.superpowers/m78-recovery2-restart-admission.json';REQUEST='.superpowers/m78-recovery2-restart-request.json';ACK='.superpowers/m78-recovery2-restart-ack.json';LOGS='.superpowers/m78-recovery2-restart-startup-logs.jsonl';STARTUP='.superpowers/m78-recovery2-restart-startup.json'
BUN='C:/Users/nimab/.bun/bin/bun.exe';BUNX='C:/Users/nimab/.bun/bin/bunx.exe';VALIDATOR='.superpowers/m78-recovery2-validate-for-restart.ts'
COLLECTOR='.superpowers/m78-recovery2-collect-startup2.py'
HELPERS=['.superpowers/m78-recovery2-validate-for-restart.ts','.superpowers/m78-recovery2-restart-admit.py','.superpowers/m78-recovery2-request-restart.py','.superpowers/m78-recovery2-collect-startup.py']
READY={'status':'ready','profile':'neuvetra.private-synthetic-staging.v1','schemaVersion':21,'legacyContainmentVerified':True}
sha=lambda value:hashlib.sha256(value).hexdigest()
def parse_time(value):return datetime.fromisoformat(value.replace('Z','+00:00'))
def exact_runtime(value):return value=={'commit':COMMIT,'deploymentId':DEPLOYMENT,'imageDigest':IMAGE,'autodeploy':False}
def command(run,args):
 result=run(args,capture_output=True,timeout=120)
 if result.returncode!=0:raise RuntimeError('provider/read validation failed')
 return result.stdout
def exclusive_bytes(path,raw):
 with Path(path).open('xb') as file:file.write(raw);file.flush();os.fsync(file.fileno())
def parse_startup_events(log_raw,requested):
 events=[]
 for line in log_raw.decode('utf-8-sig').splitlines():
  row=json.loads(line)
  if not isinstance(row,dict):raise RuntimeError('malformed provider log row')
  body=row if row.get('event')=='staging_started' else None
  if body is None and isinstance(row.get('message'),str):
   try:nested=json.loads(row['message'])
   except (ValueError,TypeError):nested=None
   if isinstance(nested,dict) and nested.get('event')=='staging_started':body=nested
  if body is not None:
   timestamp=row.get('timestamp',body.get('timestamp'))
   if not isinstance(timestamp,str):raise RuntimeError('startup timestamp')
   try:parsed=parse_time(timestamp)
   except (ValueError,TypeError):raise RuntimeError('startup timestamp') from None
   if parsed>requested:events.append({'event':'staging_started','timestamp':timestamp})
 unique={(event['event'],event['timestamp']):event for event in events}
 if len(unique)!=1:raise RuntimeError('expected exactly one unique post-request startup')
 return next(iter(unique.values()))
def collect_startup(request_path,request_sha256,ack_path,ack_sha256,run=subprocess.run,urlopen=urllib.request.urlopen,now=lambda:datetime.now(timezone.utc)):
 if request_path!=REQUEST or ack_path!=ACK or len(request_sha256)!=64 or len(ack_sha256)!=64:raise RuntimeError('request arguments')
 request_raw=Path(request_path).read_bytes();ack_raw=Path(ack_path).read_bytes()
 if sha(request_raw)!=request_sha256 or sha(ack_raw)!=ack_sha256:raise RuntimeError('request or acknowledgment pin')
 request=json.loads(request_raw);ack=json.loads(ack_raw)
 if request.get('status')!='m78_readonly_recovery2_restart_requested' or request.get('reason')!='scope1_persistence_verification' or not exact_runtime(request.get('runtime')) or ack!={'data':{'deploymentRestart':True}}:raise RuntimeError('request or acknowledgment body')
 admission_raw=Path(ADMISSION).read_bytes()
 if sha(admission_raw)!=request.get('restartAdmissionSha256'):raise RuntimeError('restart admission pin')
 admission=json.loads(admission_raw);qa=admission['actualQa']
 pins=admission.get('restartHelperPins')
 if not isinstance(pins,list) or [pin.get('path') for pin in pins]!=HELPERS:raise RuntimeError('restart helper pins')
 for pin in pins:
  if sha(Path(pin['path']).read_bytes())!=pin.get('sha256'):raise RuntimeError('restart helper changed')
 validated=json.loads(command(run,[BUN,'run',VALIDATOR,qa['path'],qa['sha256']]).decode('utf-8-sig'))
 if validated!=request.get('validatedRecovery') or validated!=admission.get('validatedRecovery'):raise RuntimeError('recovery2 validation changed')
 if Path(LOGS).exists() or Path(STARTUP).exists():raise RuntimeError('startup collection already exists')
 requested=parse_time(request['requestedAt']);collection_until=now()
 if not requested<collection_until:raise RuntimeError('request chronology')
 cli=[BUNX,'@railway/cli'];rows_raw=command(run,cli+['deployment','list','--project',PROJECT,'--service',SERVICE,'--environment',ENVIRONMENT,'--json']);rows=json.loads(rows_raw.decode('utf-8-sig'))
 active=[row for row in rows if row.get('status') not in ('REMOVED','FAILED','CRASHED','SKIPPED')]
 if len(active)!=1:raise RuntimeError('ambiguous active deployments')
 row=active[0]
 if row.get('id')!=DEPLOYMENT or row.get('status')!='SUCCESS' or row.get('meta',{}).get('commitHash')!=COMMIT or row.get('meta',{}).get('imageDigest')!=IMAGE:raise RuntimeError('wrong provider deployment')
 auto_query=f'query {{ serviceInstanceAutoDeployStatus(environmentId:"{ENVIRONMENT}",projectId:"{PROJECT}",serviceId:"{SERVICE}") {{ enabled }} }}'
 auto_raw=command(run,cli+['api',auto_query,'--compact']);auto=json.loads(auto_raw.decode('utf-8-sig'))
 if auto.get('errors') or auto.get('data',{}).get('serviceInstanceAutoDeployStatus',{}).get('enabled') is not False:raise RuntimeError('autodeploy not disabled')
 log_args=cli+['logs',DEPLOYMENT,'--project',PROJECT,'--environment',ENVIRONMENT,'--service',SERVICE,'--deployment','--since',request['requestedAt'],'--until',collection_until.isoformat(),'--lines','1000','--json']
 log_raw=command(run,log_args);startup_event=parse_startup_events(log_raw,requested)
 if parse_time(startup_event['timestamp'])>collection_until:raise RuntimeError('future startup event')
 with urlopen('https://www.neuvetra.ai/ready',timeout=30) as response:
  if response.status!=200:raise RuntimeError('readiness status')
  ready=json.load(response)
 if ready!=READY:raise RuntimeError('readiness body')
 observed=now()
 if observed<collection_until:raise RuntimeError('observation clock')
 sanitized=(json.dumps(startup_event,separators=(',',':'))+'\n').encode()
 receipt={'status':'m78_readonly_recovery2_restart_startup_observed','requestSha256':request_sha256,'acknowledgmentSha256':ack_sha256,'requestId':request['requestId'],'startupEvents':1,'providerStartup':startup_event,'observedAt':observed.isoformat(),'ready':ready,'runtime':{'commit':COMMIT,'deploymentId':DEPLOYMENT,'imageDigest':IMAGE,'autodeploy':False},'providerEvidence':{'collectionUntil':collection_until.isoformat(),'startupLogsSha256':sha(sanitized),'deploymentRowsSha256':sha(rows_raw),'autodeployResponseSha256':sha(auto_raw),'collector':{'path':COLLECTOR,'sha256':sha(Path(COLLECTOR).read_bytes())}}}
 exclusive_bytes(LOGS,sanitized);exclusive_bytes(STARTUP,(json.dumps(receipt,indent=2)+'\n').encode());return receipt
def main(argv):
 if len(argv)!=6 or argv[1]!='--execute':raise SystemExit('Usage: m78-recovery2-collect-startup2.py --execute REQUEST_PATH REQUEST_SHA256 ACK_PATH ACK_SHA256')
 print(json.dumps(collect_startup(argv[2],argv[3],argv[4],argv[5])))
if __name__=='__main__':
 if not __debug__:raise RuntimeError('Optimized execution refused')
 main(sys.argv)

import hashlib, importlib.util, io, json, os, shutil, tempfile, unittest
from datetime import datetime, timezone
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
spec=importlib.util.spec_from_file_location('collector2',ROOT/'.superpowers/m78-recovery2-collect-startup2.py')
collector=importlib.util.module_from_spec(spec);spec.loader.exec_module(collector)
sha=lambda value:hashlib.sha256(value).hexdigest()

class Response(io.BytesIO):
 status=200
 def __enter__(self):return self
 def __exit__(self,*_):self.close()

class Result:
 def __init__(self,stdout=b'',returncode=0):self.stdout=stdout;self.returncode=returncode;self.stderr=b''

class Boundary:
 def __init__(self,validated,logs):self.validated=validated;self.logs=logs;self.log_args=None
 def __call__(self,args,**_kwargs):
  joined=' '.join(args)
  if args[0].endswith('bun.exe'):return Result(json.dumps(self.validated).encode())
  if 'deployment list' in joined:return Result(json.dumps([{'id':collector.DEPLOYMENT,'status':'SUCCESS','meta':{'commitHash':collector.COMMIT,'imageDigest':collector.IMAGE}}]).encode())
  if 'serviceInstanceAutoDeployStatus' in joined:return Result(json.dumps({'data':{'serviceInstanceAutoDeployStatus':{'enabled':False}}}).encode())
  if ' logs ' in ' '+joined+' ':
   self.log_args=args
   return Result(self.logs)
  raise AssertionError(args)

class CollectorRepair(unittest.TestCase):
 def setUp(self):
  self.requested=datetime(2026,9,23,4,33,48,tzinfo=timezone.utc)

 def rows(self,*rows):return ('\n'.join(json.dumps(row) for row in rows)+'\n').encode()

 def test_flat_observed_shape_and_nested_legacy_shape(self):
  flat=self.rows({'profile':'service','timestamp':'2026-09-23T04:34:08.743321887Z','message':'','level':'info','event':'staging_started'})
  nested=self.rows({'timestamp':'2026-09-23T04:34:09Z','message':json.dumps({'event':'staging_started'})})
  self.assertEqual(collector.parse_startup_events(flat,self.requested),{'event':'staging_started','timestamp':'2026-09-23T04:34:08.743321887Z'})
  self.assertEqual(collector.parse_startup_events(nested,self.requested),{'event':'staging_started','timestamp':'2026-09-23T04:34:09Z'})

 def test_exact_duplicates_dedupe_but_distinct_startups_refuse(self):
  row={'timestamp':'2026-09-23T04:34:08Z','message':'','event':'staging_started'}
  self.assertEqual(collector.parse_startup_events(self.rows(row,row),self.requested)['timestamp'],row['timestamp'])
  with self.assertRaisesRegex(RuntimeError,'exactly one'):
   collector.parse_startup_events(self.rows(row,{**row,'timestamp':'2026-09-23T04:34:09Z'}),self.requested)

 def test_malformed_rows_refuse(self):
  with self.assertRaises((json.JSONDecodeError,RuntimeError)):collector.parse_startup_events(b'{broken\n',self.requested)
  with self.assertRaisesRegex(RuntimeError,'timestamp'):
   collector.parse_startup_events(self.rows({'event':'staging_started','message':''}),self.requested)

 def test_full_mock_uses_unfiltered_logs_and_records_collector_provenance(self):
  with tempfile.TemporaryDirectory() as directory:
   old=os.getcwd();os.chdir(directory)
   try:
    Path('.superpowers').mkdir()
    for path in collector.HELPERS+[collector.COLLECTOR,collector.ADMISSION,collector.REQUEST,collector.ACK]:
     target=Path(path);target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(ROOT/path,target)
    request_raw=Path(collector.REQUEST).read_bytes();ack_raw=Path(collector.ACK).read_bytes();request=json.loads(request_raw)
    logs=self.rows({'timestamp':'2026-09-23T04:34:08.743321887Z','event':'staging_started','message':'','profile':'service','level':'info'})
    boundary=Boundary(request['validatedRecovery'],logs)
    ready=lambda *_args,**_kwargs:Response(json.dumps(collector.READY).encode())
    receipt=collector.collect_startup(collector.REQUEST,sha(request_raw),collector.ACK,sha(ack_raw),boundary,ready,lambda:datetime(2026,9,23,4,35,tzinfo=timezone.utc))
    self.assertNotIn('--filter',boundary.log_args)
    self.assertEqual(receipt['providerStartup']['timestamp'],'2026-09-23T04:34:08.743321887Z')
    self.assertEqual(receipt['providerEvidence']['collector'],{'path':collector.COLLECTOR,'sha256':sha(Path(collector.COLLECTOR).read_bytes())})
    self.assertEqual(Path(collector.LOGS).read_text(),'{"event":"staging_started","timestamp":"2026-09-23T04:34:08.743321887Z"}\n')
   finally:os.chdir(old)

if __name__=='__main__':unittest.main()
